#### Signature Verification  
If your platform has a secret configured, DrorPay will include a signature header:  
```
X-DrorPay-Signature: sha256=<hmac_signature>
```  
**Verification Example (Node.js)**:
```javascript
const crypto = require('crypto');

function verifyWebhookSignature(payload, signature, secret) {
const expectedSignature = crypto
.createHmac('sha256', secret)
.update(JSON.stringify(payload))
.digest('hex');

return `sha256=${expectedSignature}` === signature;
}

// In your webhook handler
app.post('/webhooks/drorpay', (req, res) => {
const signature = req.headers['x-drorpay-signature'];
const payload = req.body;

if (signature && !verifyWebhookSignature(payload, signature, YOUR_PLATFORM_SECRET)) {
return res.status(401).send('Invalid signature');
}

// Process webhook
handleWebhook(payload);
res.status(200).send('OK');
});
```

