#### 4. Webhook Integration
```javascript
// Platform webhook endpoint
app.post('/webhooks/drorpay', express.json(), (req, res) => {
const signature = req.headers['x-drorpay-signature'];
const payload = req.body;

// Verify webhook signature
if (signature && !verifyWebhookSignature(payload, signature, PLATFORM_SECRET)) {
return res.status(401).send('Invalid signature');
}

