this.xKey = process.env.SOLA_X_KEY;
}

async processCreditCardPayment(paymentData) {
const {
userId,
amount,
card_token,
cvv,
description = "Wallet Top-up"
} = paymentData;

// Create payment transaction record
const transaction = await solaTransactions.create({
user_id: userId,
