const solaRequest = {
xKey: this.xKey,
xVersion: "5.0.0",
xSoftwareName: "drorpay.org",
xSoftwareVersion: "1.0.0",
xCommand: "cc:sale",
xAmount: amount.toString(),
xToken: card_token,
xCVV: cvv,
xInvoice: transaction.id,
xDescription: description,
xAllowDuplicate: "false"
};

// Send request to Sola
const response = await axios.post(this.apiUrl, new URLSearchParams(solaRequest), {
headers: {
"Accept": "application/json",
"X-Recurring-Api-Version": "2.1"
},
timeout: 30000
});

const solaResponse = Object.fromEntries(new URLSearchParams(response.data));

// Update transaction with response
await transaction.update({
sola_transaction_id: solaResponse.xRefNum,
sola_response: solaResponse,
status: solaResponse.xResult === "A" ? "completed" : "failed",
failure_reason: solaResponse.xError || null
});

return {
success: solaResponse.xResult === "A",
transaction_id: transaction.id,
sola_response: solaResponse
};
}
}
