const tokens = await fcmTokenRepository.findByUserId(userId);

if (tokens.length === 0) {
return { success: false, reason: 'No FCM tokens found' };
}

const message = {
notification: {
title,
body
},
data: {
...data,
timestamp: new Date().toISOString()
},
tokens: tokens.map(token => token.fcm_token)
};

try {
const response = await admin.messaging().sendMulticast(message);

// Handle failed tokens
if (response.failureCount > 0) {
const failedTokens = [];
response.responses.forEach((resp, idx) => {
if (!resp.success) {
failedTokens.push(tokens[idx].fcm_token);
}
});

// Remove invalid tokens
await fcmTokenRepository.removeTokens(failedTokens);
}

return {
success: true,
successCount: response.successCount,
failureCount: response.failureCount
};
} catch (error) {
console.error('Push notification error:', error);
return { success: false, error: error.message };
}
}
